<?php
declare(strict_types=1);defined('_JEXEC')or die;use Joomla\CMS\Language\Text;use Joomla\CMS\Router\Route;$s=htmlspecialchars((string)$params->get('moduleclass_sfx',''),ENT_QUOTES,'UTF-8');
?><div class="mod-joomleague-spotlight<?php echo$s;?>"><?php if(isset($spotlight['error'])):?><div class="alert alert-info mb-0"><?php echo Text::_($spotlight['error']);?></div><?php else:$item=$spotlight['item'];$url=$item->kind==='person'?'index.php?option=com_joomleague&view=person&person_id='.(int)$item->id:'index.php?option=com_joomleague&view=team&team_id='.(int)$item->id;?><article class="card h-100"><div class="card-body"><div class="d-flex gap-3 align-items-start"><?php if((int)$params->get('show_image',1)===1&&$item->image):?><img src="<?php echo htmlspecialchars((string)$item->image,ENT_QUOTES,'UTF-8');?>" alt="" width="96" height="96" class="img-fluid" loading="lazy"><?php else:?><span class="<?php echo$item->kind==='person'?'icon-user':'icon-users';?> fs-2 text-body-secondary" aria-hidden="true"></span><?php endif;?><div class="flex-grow-1"><span class="badge text-bg-secondary mb-2"><?php echo Text::_('MOD_JOOMLEAGUE_SPOTLIGHT_KIND_'.strtoupper((string)$item->kind));?></span><h3 class="h5 mb-1"><a class="stretched-link text-decoration-none" href="<?php echo Route::_($url);?>"><?php echo htmlspecialchars((string)$item->display_name,ENT_QUOTES,'UTF-8');?></a></h3><?php if((int)$params->get('show_context',1)===1&&$item->context_name):?><div class="text-body-secondary"><?php echo htmlspecialchars((string)$item->context_name,ENT_QUOTES,'UTF-8');?></div><?php endif;?></div></div><?php if((int)$params->get('show_description',1)===1&&$item->excerpt!==''):?><p class="card-text mt-3 mb-0"><?php echo htmlspecialchars((string)$item->excerpt,ENT_QUOTES,'UTF-8');?><?php echo mb_strlen(trim(strip_tags((string)$item->description)))>mb_strlen((string)$item->excerpt)?'…':'';?></p><?php endif;?></div></article><?php endif;?></div>
